+interface UnitInfo {
+  kind: Kind | "temperature";
+  factor?: number;
+}
+
+function lookup(symbol: string): UnitInfo | undefined {
+  const linear = LINEAR_UNITS[symbol];
+  if (linear) return { kind: linear.kind, factor: linear.factor };
+  if ((TEMPERATURE_UNITS as readonly string[]).includes(symbol)) {
+    return { kind: "temperature" };
+  }
+  return undefined;
+}
+
+function toCelsius(value: number, unit: string): number {
+  switch (unit) {
+    case "C":
+      return value;
+    case "F":
+      return ((value - 32) * 5) / 9;
+    default:
+      return value - 273.15;
+  }
+}
+
+function fromCelsius(celsius: number, unit: string): number {
+  switch (unit) {
+    case "C":
+      return celsius;
+    case "F":
+      return (celsius * 9) / 5 + 32;
+    default:
+      return celsius + 273.15;
+  }
+}
